'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var format = require( '@stdlib/string/format' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var tryRequire = require( '@stdlib/utils/try-require' );
var pkg = require( './../package.json' ).name;


// VARIABLES //

var heaviside = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( heaviside instanceof Error )
};


// MAIN //

bench( format( '::native', pkg, opts ), function benchmark( b ) {
	var x;
	var y;
	var i;

	x = uniform( 100, -50.0, 50.0 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		// DISCONTINUOUS
		y = heaviside( x[ i%x.length ] );
		if ( y > 1.0 ) {
			b.fail( 'should not return a value greater than 1' );
		}
	}
	b.toc();
	if ( y > 1.0 ) {
		b.fail( 'should not return a value greater than 1' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '::native:left-continuous', pkg, opts ), function benchmark( b ) {
	var x;
	var y;
	var i;

	x = uniform( 100, -50.0, 50.0 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		// LEFT_CONTINUOUS
		y = heaviside( x[ i%x.length ], 1 );
		if ( isnan( y ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( y ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

